import { v } from "convex/values";
import { mutation, type QueryCtx } from "./_generated/server";
import type { Id } from "./_generated/dataModel";
import { r2, SIX_HOURS } from "./r2";
import { assertWorker } from "./broll";

// Smart edits (Phase 3): AI-generated edit decisions per clip (SmartEdit in
// types/clip.ts), generated by the worker (render-worker/smart-edit.mjs) and
// tweaked by the user in the clip editor.

async function ownClip(ctx: QueryCtx, clipId: Id<"clips">) {
  const identity = await ctx.auth.getUserIdentity();
  if (!identity) throw new Error("Unauthorized");
  const clip = await ctx.db.get(clipId);
  if (!clip || clip.userId !== identity.subject) throw new Error("Not found");
  return clip;
}

function assertSmartShape(smart: unknown) {
  const s = smart as Record<string, unknown> | null;
  if (
    !s ||
    s.version !== 1 ||
    !Array.isArray(s.removals) ||
    !Array.isArray(s.zooms) ||
    !Array.isArray(s.highlights) ||
    !Array.isArray(s.broll) ||
    typeof s.reframe !== "object" ||
    typeof s.hook !== "object" ||
    typeof s.anim !== "object"
  ) {
    throw new Error("Invalid smart edit");
  }
  if (JSON.stringify(s).length > 400_000) throw new Error("Smart edit too large");
}

// User tweaks: the editor sends the whole updated SmartEdit.
export const save = mutation({
  args: { clipId: v.id("clips"), smart: v.any() },
  handler: async (ctx, { clipId, smart }) => {
    await ownClip(ctx, clipId);
    assertSmartShape(smart);
    await ctx.db.patch(clipId, { smart });
    return null;
  },
});

export const regenerate = mutation({
  args: { clipId: v.id("clips") },
  handler: async (ctx, { clipId }) => {
    const clip = await ownClip(ctx, clipId);
    if (clip.smartStatus === "queued" || clip.smartStatus === "processing") return null;
    await ctx.db.patch(clipId, { smartStatus: "queued", smartError: null, smartQueuedAt: Date.now() });
    return null;
  },
});

// ── Worker-facing (shared secret) ──

export const claimNext = mutation({
  args: { secret: v.string() },
  handler: async (ctx, { secret }) => {
    assertWorker(secret);
    const now = Date.now();
    let clip = await ctx.db
      .query("clips")
      .withIndex("by_smart_status", (q) => q.eq("smartStatus", "queued"))
      .first();
    if (!clip) {
      clip = await ctx.db
        .query("clips")
        .withIndex("by_smart_status", (q) => q.eq("smartStatus", "processing"))
        .filter((q) => q.lt(q.field("smartStartedAt"), now - 20 * 60 * 1000))
        .first();
    }
    if (!clip) return null;
    const source = await ctx.db.get(clip.sourceId);
    if (!source) {
      await ctx.db.patch(clip._id, { smartStatus: "failed", smartError: "Source video was deleted" });
      return null;
    }
    await ctx.db.patch(clip._id, { smartStatus: "processing", smartStartedAt: now });

    const chunks = await ctx.db
      .query("clipTranscripts")
      .withIndex("by_source", (q) => q.eq("sourceId", source._id))
      .collect();
    const words: { w: string; s: number; e: number }[] = [];
    for (const c of chunks.sort((a, b) => a.chunk - b.chunk)) {
      for (const w of c.words) if (w.e > clip.start && w.s < clip.end) words.push(w);
    }
    return {
      id: clip._id,
      userId: clip.userId,
      title: clip.title,
      hook: clip.hook,
      sourceUrl: await r2.getUrl(source.videoKey, { expiresIn: SIX_HOURS }),
      start: clip.start,
      end: clip.end,
      aspect: clip.aspect ?? "9:16",
      words,
      previous: clip.smart ?? null,
    };
  },
});

export const saveGenerated = mutation({
  args: { secret: v.string(), clipId: v.id("clips"), smart: v.any() },
  handler: async (ctx, { secret, clipId, smart }) => {
    assertWorker(secret);
    assertSmartShape(smart);
    await ctx.db.patch(clipId, { smart, smartStatus: "ready", smartError: null });
    return null;
  },
});

export const fail = mutation({
  args: { secret: v.string(), clipId: v.id("clips"), error: v.string() },
  handler: async (ctx, { secret, clipId, error }) => {
    assertWorker(secret);
    await ctx.db.patch(clipId, { smartStatus: "failed", smartError: error.slice(0, 500) });
    return null;
  },
});
